import collections
from time import sleep
from ute_common_store import Store
from ute_ipsec.executor import Executor
from ute_ipsec.vlan import BtsVlans, SecgwVlans
from ute_ipsec.ipsec import BTSIpsec, SecGwIpsec, ControlServer


IpSecObjects = collections.namedtuple('IpSecObjects', ['bts_ipsec', 'secgw_ipsec', 'bts_vlans', 'secgw_vlans', 'control_server'])


class ute_ipsec(object):
    """ Ipsec is an encryption/decryption feature handled by Strongswan software.
        This library provides keywords to control Ipsec on the BTS and Secure gateway.
        This library supports aliases.
    """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self.store = Store()

    def setup_ipsec(self, tl_vlan_ids, sec_gw_ip='127.0.0.1', alias=None):
        """Sets up the library for ipsec operations.
        :param tl_vlan_ids: list of vlan_ids integers, from the testline configuration.
        :param sec_gw_ip: secure gateway ip, from the testline configuration, if it is on a remote server.
        Default is local host. UTE testlines have secgw running locally.
        """
        alias = alias.strip() if alias is not None else None
        executor = Executor.create(sec_gw_ip)
        ip_sec = IpSecObjects(BTSIpsec(executor, sec_gw_ip), SecGwIpsec(executor, sec_gw_ip), BtsVlans(tl_vlan_ids, sec_gw_ip),
                              SecgwVlans(tl_vlan_ids, executor, sec_gw_ip), ControlServer(executor))
        self.store.add(ip_sec, alias=alias)

    def configure_ipsec(self, number_of_vlans=4, ip_version=4, configuration='basic', config_file='default', alias=None):
        """Creates vlans on the sec_gw and bts and configures ipsec policies on BTS.
        :param number_of_vlans: required number of vlans to be configured, default is 4, datatype is integer
        :param ip_version: ip version (4 for Ipv4 and 6 for Ipv6) to be passed as integer, default is 4
        :param: configuration: used for performing '8 ip' configuration [Ipv4], default is 'basic'
        :param: config_file: delta commissioning file for Vlans configuration on BTS
        """
        self._get_ipsec_from_store(alias).bts_ipsec.add_certificate()
        self._get_ipsec_from_store(alias).secgw_vlans.create(number_of_vlans, int(ip_version), configuration, config_file)
        self._get_ipsec_from_store(alias).bts_vlans.create(number_of_vlans, int(ip_version), configuration, config_file)
        # self._get_ipsec_from_store(alias).bts_ipsec.configure_policies(number_of_vlans, int(ip_version), configuration, config_file)
        sleep(60)       # vlans are not ready on BTS sometimes, until this time

    def enable_ipsec(self, ip_version=4, configuration='basic', ipsec_conf_file='default', alias=None):
        """Enables IPSec on the secgw and the BTS. Verifies if Security Associations and ESP SPI IDs are established"""
        self._get_ipsec_from_store(alias).secgw_ipsec.enable(ipsec_conf_file)
        self._get_ipsec_from_store(alias).bts_ipsec.enable()
        sleep(60)  # security associations are not ready, until this time
        self._get_ipsec_from_store(alias).secgw_ipsec.check_all_states()
        self._get_ipsec_from_store(alias).bts_ipsec.check_all_states()
        self._get_ipsec_from_store(alias).bts_ipsec.verify_ipsec_traffic(int(ip_version), configuration)

    def enable_ipsec_on_bts(self, alias=None):
        """Enables IPSec on the BTS."""
        self._get_ipsec_from_store(alias).bts_ipsec.enable()

    def enable_ipsec_on_secgw(self, ipsec_conf_file='default', alias=None):
        """Enables IPSec on the secgw."""
        self._get_ipsec_from_store(alias).secgw_ipsec.enable(ipsec_conf_file)

    def bring_control_server_up(self, ip_version=4, alias=None):
        """Creates a virtual interface on secgw for emergency by-pass control."""
        self._get_ipsec_from_store(alias).control_server.bring_control_server_up(int(ip_version))

    def bring_control_server_down(self, ip_version=4, alias=None):
        """Brings down the virtual interface on vm
        :param ip_version: ip version (4 for Ipv4 and 6 for Ipv6) to be passed as integer, default is 4"""
        self._get_ipsec_from_store(alias).control_server.bring_control_server_down(int(ip_version))

    def turn_on_emergency_bypass_feature(self, ip_version=4, alias=None):
        """Enables the emergency by-pass feature on BTS
        :param ip_version: ip version (4 for Ipv4 and 6 for Ipv6) to be passed as integer, default is 4"""
        self._get_ipsec_from_store(alias).bts_ipsec.turn_on_emergency_bypass_feature(int(ip_version))

    def emergency_bypass_state_should_be(self, expected_state, alias=None):
        """verifies if the emergency bypass state is as expected.
        :param expected_state: bypass state that is expected. Usually (Standby|Probing|Active|Off)
        """
        self._get_ipsec_from_store(alias).bts_ipsec.emergency_bypass_state_should_be(expected_state)

    def exit_emergency_bypass(self, alias=None):
        """Exits emergency bypass from Active state"""
        self._get_ipsec_from_store(alias).bts_ipsec.exit_emergency_bypass()

    def ipsec_state_on_secgw_should_be(self, expected_state, alias=None):
        """verifies if the ipsec state on secgw is as expected
        :param expected_state: ipsec state that is expected on secure gateway.
        """
        self._get_ipsec_from_store(alias).secgw_ipsec.check_state(expected_state)

    def ipsec_state_on_bts_should_be(self, expected_state, alias=None):
        """verifies if the ipsec state on bts is as expected
        :param expected_state: ipsec state that is expected on BTS
        """
        self._get_ipsec_from_store(alias).bts_ipsec.check_state(expected_state)

    def get_ipsec_connections_states_on_secgw(self, conn=(50, 60, 70), alias=None):
        """Returns a dictionary of connection(s) states and ESP SPI IDs on secgw
        :param conn: list of connection numbers.
        """
        return self._get_ipsec_from_store(alias).secgw_ipsec.get_connections_states(conn)

    def get_ipsec_connections_states_on_bts(self, conn=(50, 60, 70), alias=None):
        """Returns a dictionary of connection(s) states and ESP SPI IDs on BTS
        :param conn: list of connection numbers.
        """
        return self._get_ipsec_from_store(alias).bts_ipsec.get_connections_states(conn)

    def get_ipsec_status_on_bts(self, alias=None):
        """Returns a string of ipsec status as is on bts"""
        status, _ = self._get_ipsec_from_store(alias).bts_ipsec.get_ipsec_status()
        return status

    def get_ipsec_status_on_secgw(self, alias=None):
        """Returns a string of ipsec status as is on secgw"""
        return self._get_ipsec_from_store(alias).secgw_ipsec.get_ipsec_status()

    def modify_ipsec_policy_parameters_on_bts(self, conn, alias=None, **parameters):
        """Modifies Ipsec policy parameters for the specified connection(s) with the specified parameter name & values on BTS
        :param conn: ipsec connection number(s). 50 for U, 60 for C, 70 for M and 80 for S planes.
        :param parameters: parameter name & value pair(s). For exact names, refer to the ipsec policies parameters in TRS SCFC
        """
        self._get_ipsec_from_store(alias).bts_ipsec.modify_ipsec_policy_parameters_on_bts(conn, **parameters)

    def modify_ipsec_policy_parameters_on_secgw(self, conn, reset=True, alias=None, **parameters):
        """Modifies Ipsec policy parameters for the specified connection(s) with the specified parameter name & values on Secgw.
        :param conn: default or ipsec connection number(s). 50 for U, 60 for C, 70 for M and 80 for S planes.
        :param reset: True for restarting ipsec on secgw after modification. Resets by default
        :param parameters: parameter name & value pair(s). For exact names, refer to the parameters in ipsec.conf file
        """
        self._get_ipsec_from_store(alias).secgw_ipsec.modify_ipsec_policy_parameters_on_secgw(conn, **parameters)
        if reset is True:
            self.restart_ipsec_on_secgw(alias)
        # Sleep required to let modified parameters into effect
        sleep(60)

    def disable_ipsec(self, alias=None):
        """Stops ipsec on secgw and bts"""
        self._get_ipsec_from_store(alias).bts_ipsec.disable()
        self._get_ipsec_from_store(alias).secgw_ipsec.disable()

    def disable_ipsec_on_secgw(self, alias=None):
        """Stops ipsec on secgw"""
        self._get_ipsec_from_store(alias).secgw_ipsec.disable()

    def disable_ipsec_on_bts(self, alias=None):
        """Stops ipsec on BTS"""
        self._get_ipsec_from_store(alias).bts_ipsec.disable()

    def restart_ipsec_on_secgw(self, alias=None):
        """Restarts ipsec on secgw"""
        self._get_ipsec_from_store(alias).secgw_ipsec.restart()

    def unconfigure_ipsec(self, number_of_vlans=4, ip_version=4, config_file='default', alias=None):
        """Removes vlans on secgw, BTS and removes policies on BTS
        :param number_of_vlans: required number of vlans to be configured, default is 4, datatype is integer
        :param ip_version: ip version (4 for Ipv4 and 6 for Ipv6) to be passed as integer, default is 4"""
        self._get_ipsec_from_store(alias).bts_ipsec.remove_policies_and_routes(number_of_vlans, int(ip_version), config_file)
        # Sleep required to let BTS available for next operation after removing policies
        sleep(60)
        self._get_ipsec_from_store(alias).bts_vlans.delete(number_of_vlans, int(ip_version), config_file)
        self._get_ipsec_from_store(alias).secgw_vlans.delete(number_of_vlans)

    def turn_off_emergency_bypass_feature(self, alias=None):
        """Disables the emergency by-pass feature on BTS"""
        self._get_ipsec_from_store(alias).bts_ipsec.turn_off_emergency_bypass_feature()

    def teardown_ipsec(self, alias=None):
        """ Disables IPsec on BTS, Secgw, Clean up the environment and remove library's settings"""
        alias = alias.strip() if alias is not None else None
        self.disable_ipsec(alias)
        self.store.remove(alias)

    def verify_security_associations_established_on_bts(self, conn=(50, 60, 70), alias=None):
        """Verifies SAs and ESP SPI IDs established on BTS for the specified connections.
        For any other verification in the SAs use get_ipsec_connections_states_on_bts or get_ipsec_status_on_bts
        :param conn: ipsec connection number or a list of connection numbers.
        """
        self._get_ipsec_from_store(alias).bts_ipsec.verify_connections_established(conn)

    def verify_security_associations_established_on_secgw(self, conn=(50, 60, 70), alias=None):
        """ Verifies SAs and ESP SPI IDs established on Secgw for the specified connections.
        For any other verification in the SAs use get_ipsec_connections_states_on_secgw or get_ipsec_status_on_segw
        :param conn: ipsec connection number or a list of connection numbers.
        """
        self._get_ipsec_from_store(alias).secgw_ipsec.verify_connections_established(conn)

    def _get_ipsec_from_store(self, alias):
        alias = alias.strip() if alias is not None else None
        return self.store.get(alias)
